-- =====================================================================
-- Descriptions v2 (26/11/2026) : style simple, chaleureux et vendeur, uniquement des faits de l'emballage.
-- Pour les bases déjà installées : remplace l'ancienne description générée par la nouvelle,
-- SEULEMENT si le texte actuel est vide ou identique à l'ancienne version.
-- Une description modifiée dans l'admin n'est JAMAIS écrasée. Ne touche à aucune autre donnée.
-- Appliqué par : npm run db:migrate, npm run db:seed, npm run db:fiches.
-- =====================================================================

-- fiche: desc-collagen | MEDIHEAL — Collagen (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Signé MEDIHEAL, Collagen se présente dans un sachet individuel rose et blanc, orné d''une illustration de flacon de sérum. Le collagène est la star de ce soin : l''emballage annonce un collagène d''une pureté de 98 % et la mention « Core Firming ». Il appartient à la gamme Mediheal Dermatology et porte la mention « Dermatology Test Completed ».'
                        THEN 'Envie d''un moment douceur ? Le masque Collagen de MEDIHEAL t''attend dans son joli sachet rose et blanc. Sa star, c''est le collagène, avec une pureté de 98 % annoncée sur l''emballage. Glisse-le dans ton pack pour une pause rien qu''à toi.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'من ⁨MEDIHEAL⁩، يأتي ⁨Collagen⁩ في كيس فردي باللونين الوردي والأبيض، مزيَّن برسم لقارورة سيروم. الكولاجين هو نجم هذا المنتج: يشير الغلاف إلى كولاجين بنقاوة 98% وإلى عبارة «⁨Core Firming⁩». ينتمي إلى مجموعة ⁨Mediheal Dermatology⁩، ويحمل عبارة «⁨Dermatology Test Completed⁩».'
                        THEN 'هل تبحثين عن لحظة دلال؟ يأتيك قناع ⁨Collagen⁩ من ⁨MEDIHEAL⁩ في كيس جميل باللونين الوردي والأبيض. نجمه هو الكولاجين، بنقاوة 98% كما هو مذكور على الغلاف. أضيفيه إلى الباك لاستراحة صغيرة خاصة بك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'By MEDIHEAL, Collagen comes in an individual pink-and-white sachet decorated with a serum bottle illustration. Collagen is the star here: the packaging announces 98% purity collagen and the words “Core Firming”. It belongs to the Mediheal Dermatology line and carries the mention “Dermatology Test Completed”.'
                        THEN 'In the mood for a cosy moment? MEDIHEAL''s Collagen mask comes in a pretty pink-and-white sachet. Its star is collagen, with 98% purity stated on the packaging. Slip it into your pack for a little break just for you.' ELSE description_en END
WHERE slug = 'collagen'
   OR (TRIM(brand) = 'MEDIHEAL' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Collagen')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%mediheal-collagen%');

-- fiche: desc-vitc | 7th Heaven — Nutriactive Vitamin C Advanced Serum Sheet Mask (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans son sachet orange vitaminé, le masque Nutriactive Vitamin C de 7th Heaven associe un « Advanced Serum » à la vitamine C (complexe actif à 5 %*) et une feuille biodégradable. La marque le présente comme un soin « Anti-Fatigue » — « Brightening + Re-Energising » — pour tous les types de peau. Il porte aussi le label Vegan de la Vegetarian Society. Une touche d''orange pleine de peps à glisser dans ton pack.'
                        THEN 'Un rayon de soleil dans ton pack ! Ce masque en tissu 7th Heaven arrive dans un sachet orange tout pétillant. Il associe un sérum à la vitamine C et une feuille biodégradable. Il convient à tous les types de peau et il est vegan : facile à adopter !' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'في كيسه البرتقالي المفعم بالحيوية، يجمع قناع ⁨Nutriactive Vitamin C⁩ من ⁨7th Heaven⁩ بين «⁨Advanced Serum⁩» بفيتامين ⁨C⁩ (مركّب نشط بنسبة 5%*) وورقة قابلة للتحلل الحيوي. تقدّمه العلامة كعناية «⁨Anti-Fatigue⁩» — «⁨Brightening + Re-Energising⁩» — لجميع أنواع البشرة، كما يحمل شعار ⁨Vegan⁩ المعتمد من ⁨Vegetarian Society⁩. لمسة برتقالية مبهجة لإضافتها إلى الباك.'
                        THEN 'شعاع شمس صغير في الباك! يأتي هذا القناع القماشي من ⁨7th Heaven⁩ في كيس برتقالي مشرق، ويجمع بين سيروم بفيتامين ⁨C⁩ وورقة قابلة للتحلل الحيوي. مناسب لجميع أنواع البشرة ونباتي (⁨Vegan⁩): اختيار سهل وممتع!' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'In its zesty orange sachet, 7th Heaven''s Nutriactive Vitamin C mask pairs an “Advanced Serum” with vitamin C (5% Active Complex*) and a biodegradable sheet. The brand presents it as an “Anti-Fatigue” treatment — “Brightening + Re-Energising” — for all skin types. It also carries the Vegetarian Society Vegan label. A bright splash of orange to add to your pack.'
                        THEN 'A ray of sunshine for your pack! This 7th Heaven sheet mask comes in a bright, zesty orange sachet. It pairs a vitamin C serum with a biodegradable sheet. Suitable for all skin types and vegan: easy to love!' ELSE description_en END
WHERE slug = 'vitc'
   OR (TRIM(brand) = '7th Heaven' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Nutriactive Vitamin C Advanced Serum Sheet Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%7th-heaven-vitamin-c%');

-- fiche: desc-green | look AT ME — Green Blend Tea Tree + Cucumber Face Mask (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Avec son sachet illustré tout en vert, Green Blend de look AT ME a un vrai charme coréen. Ce masque visage réunit l''arbre à thé et le concombre sur une feuille en Tencel, et il est fabriqué en Corée. La marque le décrit comme « Revitalizing & Soothing ». Un masque frais et ludique à ajouter à ton pack.'
                        THEN 'Tout en vert et plein de bonne humeur ! Le masque Green Blend de look AT ME réunit un joli duo : l''arbre à thé et le concombre. Avec sa feuille en Tencel et son sachet illustré, c''est un petit plaisir à partager… ou à garder pour toi. Fabriqué en Corée, 25 ml.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'بغلافه الأخضر المرسوم، يحمل ⁨Green Blend⁩ من ⁨look AT ME⁩ لمسة كورية مميّزة. يجمع هذا القناع للوجه بين شجرة الشاي والخيار على ورقة من ألياف ⁨Tencel⁩، وهو مصنوع في كوريا. تصفه العلامة بعبارة «⁨Revitalizing & Soothing⁩». قناع منعش ومرح لإضافته إلى الباك.'
                        THEN 'أخضر بالكامل ومليء بالمرح! يجمع قناع ⁨Green Blend⁩ من ⁨look AT ME⁩ بين ثنائي جميل: شجرة الشاي والخيار. بورقته من ألياف ⁨Tencel⁩ وكيسه المرسوم، هو متعة صغيرة تتشاركينها… أو تحتفظين بها لنفسك. صُنع في كوريا، 25 مل.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'With its all-green illustrated sachet, look AT ME''s Green Blend has real Korean charm. This face mask brings together tea tree and cucumber on a Tencel sheet, and it is made in Korea. The brand describes it as “Revitalizing & Soothing”. A fresh, playful mask to add to your pack.'
                        THEN 'All green and full of good vibes! look AT ME''s Green Blend mask brings together a lovely duo: tea tree and cucumber. With its Tencel sheet and illustrated sachet, it''s a little treat to share… or keep all to yourself. Made in Korea, 25 ml.' ELSE description_en END
WHERE slug = 'green'
   OR (TRIM(brand) = 'look AT ME' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Green Blend Tea Tree + Cucumber Face Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%lookatme-green-blend%');

-- fiche: desc-hazel | IDC Institute — One Week Treatment — Hazel + Lavender (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Ce masque fait partie de la gamme « One Week Treatment » d''IDC Institute : c''est le n°3, « Wednesday » (mercredi), dans un sachet violet et argent. Il associe l''hamamélis et la lavande, et la marque l''accompagne du texte « Nettoie les pores et élimine la fatigue de la peau ». L''emballage affiche le logo Cruelty free.'
                        THEN 'Mercredi, c''est son jour ! Ce masque visage IDC Institute porte le n°3 de la gamme One Week Treatment, « Wednesday ». Il réunit l''hamamélis et la lavande dans un joli sachet violet et argent. Et en plus, il est cruelty free.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'ينتمي هذا القناع إلى مجموعة «⁨One Week Treatment⁩» من ⁨IDC Institute⁩: إنه القناع رقم 3، «⁨Wednesday⁩» (الأربعاء)، في كيس بلونَي البنفسجي والفضي. يجمع بين الهماميليس واللافندر، وترفقه العلامة بعبارة «ينظّف مسام البشرة ويزيل عنها التعب». ويحمل الغلاف شعار ⁨Cruelty free⁩.'
                        THEN 'الأربعاء هو يومه! يحمل هذا القناع من ⁨IDC Institute⁩ الرقم 3 في مجموعة ⁨One Week Treatment⁩، «⁨Wednesday⁩». يجمع بين الهماميليس واللافندر في كيس أنيق بلونَي البنفسجي والفضي، وهو أيضاً ⁨Cruelty free⁩.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'This mask belongs to IDC Institute''s “One Week Treatment” line: it is no. 3, “Wednesday”, in a purple and silver sachet. It combines witch hazel and lavender, and the brand adds the text “Clean the pore of skin and remove fatique from your face”. The packaging displays the Cruelty free logo.'
                        THEN 'Wednesday is its day! This IDC Institute facial mask is no. 3 in the One Week Treatment line, “Wednesday”. It brings together witch hazel and lavender in a pretty purple and silver sachet. And it''s cruelty free, too.' ELSE description_en END
WHERE slug = 'hazel'
   OR (TRIM(brand) = 'IDC Institute' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'One Week Treatment - Hazel + Lavender')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%idc-hazel-lavender%');

-- fiche: desc-gluta | SOME BY MI — Real Glutathione Brightening Care Mask (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans un sachet épuré aux bulles roses, Real Glutathione Brightening Care Mask de SOME BY MI est un masque à feuille 100 % d''origine végétale et biodégradable, formulé avec du glutathion. D''après le texte de l''emballage, il « redonne de la vitalité aux peaux ternes et favorise un teint plus lumineux et plus uniforme ». La marque l''accompagne des mentions « Moisturizing | Radiance » et « Dermatologist Tested ».'
                        THEN 'Simple, élégant et tout en bulles roses ! Le masque Real Glutathione de SOME BY MI est formulé avec du glutathion, sur une feuille 100 % végétale et biodégradable. Testé dermatologiquement, il trouvera vite sa place dans ton pack.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'في كيس أنيق تزيّنه فقاعات وردية، يأتي ⁨Real Glutathione Brightening Care Mask⁩ من ⁨SOME BY MI⁩: قناع بورقة نباتية 100% وقابلة للتحلل الحيوي، مركّب بالغلوتاثيون. وبحسب النص المطبوع على الغلاف، فهو «يُنعش البشرة الباهتة ويساعد على الحصول على بشرة أكثر إشراقاً وتجانساً في اللون». وترفقه العلامة بعبارتي «⁨Moisturizing | Radiance⁩» و«⁨Dermatologist Tested⁩».'
                        THEN 'بسيط وأنيق ومليء بالفقاعات الوردية! قناع ⁨Real Glutathione⁩ من ⁨SOME BY MI⁩ مركّب بالغلوتاثيون، على ورقة نباتية 100% وقابلة للتحلل الحيوي. مختبَر جلدياً، وسيجد مكانه بسرعة في الباك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'In a clean sachet with pink bubbles, SOME BY MI''s Real Glutathione Brightening Care Mask is a 100% plant-based biodegradable sheet mask formulated with Real Glutathione. According to the packaging, it “revitalizes dull skin and promotes a brighter, more even skin tone”. The brand adds the mentions “Moisturizing | Radiance” and “Dermatologist Tested”.'
                        THEN 'Simple, elegant and full of pink bubbles! SOME BY MI''s Real Glutathione mask is formulated with glutathione, on a 100% plant-based, biodegradable sheet. Dermatologist tested, it will soon find its place in your pack.' ELSE description_en END
WHERE slug = 'gluta'
   OR (TRIM(brand) = 'SOME BY MI' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Real Glutathione Brightening Care Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%some-by-mi-glutathione%');

-- fiche: desc-rosegold | masque BAR — Rose Gold Foil Sheet Mask (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Avec son sachet élégant aux reflets rose doré, le Rose Gold Foil Sheet Mask de masque BAR (Unmasque Beauty) apporte une touche chic à ton pack. D''après l''emballage, il est « enrichi d''extraits qui aident à nourrir et hydrater la peau » et met en avant l''extrait de soja, l''extrait de champignon et l''eau d''hamamélis.'
                        THEN 'Une touche de glamour dans ton pack ! Le Rose Gold Foil Sheet Mask de masque BAR brille dans son sachet rose doré. À l''intérieur : un masque complet de 30 ml, avec extrait de soja, extrait de champignon et eau d''hamamélis. Idéal pour une soirée cocooning entre copines… ou en solo.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'بكيسه الأنيق بلون الذهب الوردي، يضيف ⁨Rose Gold Foil Sheet Mask⁩ من ⁨masque BAR⁩ (⁨Unmasque Beauty⁩) لمسة راقية إلى الباك. وبحسب الغلاف، فهو «غني بمستخلصات تساعد على تغذية البشرة وترطيبها»، ويبرز مستخلص فول الصويا ومستخلص الفطر وماء الهماميليس.'
                        THEN 'لمسة فخامة في الباك! يتألق قناع ⁨Rose Gold Foil Sheet Mask⁩ من ⁨masque BAR⁩ في كيسه بلون الذهب الوردي. في الداخل: قناع كامل بحجم 30 مل، بمستخلص فول الصويا ومستخلص الفطر وماء الهماميليس. مثالي لسهرة دلال مع الصديقات… أو بمفردك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'With its elegant rose-gold sachet, masque BAR''s Rose Gold Foil Sheet Mask (Unmasque Beauty) brings a chic touch to your pack. According to the packaging, it is “enriched with extracts that help nourish and hydrate your skin” and highlights soybean extract, mushroom extract and witch hazel water.'
                        THEN 'A touch of glam for your pack! masque BAR''s Rose Gold Foil Sheet Mask shines in its rose-gold sachet. Inside: one complete 30 ml mask with soybean extract, mushroom extract and witch hazel water. Ideal for a cosy night in with friends… or solo.' ELSE description_en END
WHERE slug = 'rosegold'
   OR (TRIM(brand) = 'masque BAR' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Rose Gold Foil Sheet Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%masquebar-rose-gold-foil%');

-- fiche: desc-orjena-power-collagen-emulsion | ORJENA — Power Collagen Emulsion (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans son flacon bordeaux au bouchon argenté, Power Collagen Emulsion d''ORJENA est une émulsion qui met le collagène à l''honneur dès son nom. La marque la présente autour de trois mentions imprimées sur l''emballage — « Skin Elasticity », « Skin Nutrition » et « Refresh » — et l''indique pour tous les types de peau. Un geste tout en douceur à glisser dans ta routine, juste après le nettoyage et la tonification.'
                        THEN 'Un flacon bordeaux chic et une émulsion au collagène : Power Collagen Emulsion d''ORJENA a tout pour te plaire ! Elle convient à tous les types de peau et se glisse facilement dans ta routine, juste après le nettoyage et le tonique. 100 ml à garder à portée de main.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'في قارورتها العنابية ذات الغطاء الفضي، تضع ⁨Power Collagen Emulsion⁩ من ⁨ORJENA⁩ الكولاجين في الواجهة منذ اسمها. تقدّمها العلامة من خلال ثلاث عبارات مطبوعة على العلبة — «⁨Skin Elasticity⁩» و«⁨Skin Nutrition⁩» و«⁨Refresh⁩» — وهي مناسبة لجميع أنواع البشرة. خطوة لطيفة تضيفينها إلى روتينك مباشرة بعد التنظيف واستعمال التونر.'
                        THEN 'قارورة عنابية أنيقة ومستحلب بالكولاجين: ⁨Power Collagen Emulsion⁩ من ⁨ORJENA⁩ فيها كل ما يعجبك! مناسبة لجميع أنواع البشرة، وتندمج بسهولة في روتينك مباشرة بعد التنظيف والتونر. 100 مل لتبقى دائماً في متناول يدك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'In its burgundy bottle with a silver cap, ORJENA''s Power Collagen Emulsion puts collagen in the spotlight right from its name. The brand presents it with three mentions printed on the packaging — “Skin Elasticity”, “Skin Nutrition” and “Refresh” — and recommends it for all skin types. A gentle step to add to your routine, right after cleansing and toning.'
                        THEN 'A chic burgundy bottle and a collagen emulsion: ORJENA''s Power Collagen Emulsion has everything to win you over! Suitable for all skin types, it slips easily into your routine, right after cleansing and toning. 100 ml to keep close at hand.' ELSE description_en END
WHERE slug = 'orjena-power-collagen-emulsion' OR (TRIM(brand) = 'ORJENA' AND TRIM(name) = 'Power Collagen Emulsion');

-- fiche: desc-somebymi-yuja-niacin-anti-blemish-cream | SOME BY MI — Yuja Niacin Anti Blemish Cream (description) | 
UPDATE products SET
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans sa boîte jaune soleil, Yuja Niacin Anti Blemish Cream de SOME BY MI associe l''extrait de yuja — un agrume coréen — à 5 % de niacinamide, comme l''indique l''emballage. Son nom la présente comme une crème « Anti Blemish » (anti-imperfections) et la marque précise qu''elle a été testée non comédogène. Un pot de 60 g plein de peps à ajouter à ta routine.'
                        THEN 'Un pot jaune soleil qui donne le sourire ! La crème Yuja Niacin de SOME BY MI associe l''extrait de yuja, un agrume coréen, à 5 % de niacinamide. Testée non comédogène selon la marque, elle s''applique en couche fine dans ta routine. Un pot de 60 g plein de peps.' ELSE description_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'في علبتها الصفراء المشرقة، يجمع ⁨Yuja Niacin Anti Blemish Cream⁩ من ⁨SOME BY MI⁩ بين مستخلص اليوجا — وهو حمضيات كورية — و5% من النياسيناميد، كما هو مكتوب على العلبة. يقدّمه اسمه ككريم «⁨Anti Blemish⁩» (مضادّ للشوائب)، وتوضّح العلامة أنه مختبَر بأنه لا يسدّ المسام. علبة بوزن 60 غرام مليئة بالحيوية تضيفينها إلى روتينك.'
                        THEN 'علبة صفراء مشرقة تبعث على الابتسامة! يجمع كريم ⁨Yuja Niacin⁩ من ⁨SOME BY MI⁩ بين مستخلص اليوجا، وهو حمضيات كورية، و5% من النياسيناميد. مختبَر بأنه لا يسدّ المسام حسب العلامة، ويُطبَّق بطبقة رقيقة ضمن روتينك. علبة بوزن 60 غرام مليئة بالحيوية.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'In its sunny yellow box, SOME BY MI''s Yuja Niacin Anti Blemish Cream pairs yuja extract — a Korean citrus fruit — with 5% niacinamide, as stated on the packaging. Its name presents it as an “Anti Blemish” cream, and the brand states that it has been tested non-comedogenic. A cheerful 60 g jar to add to your routine.'
                        THEN 'A sunny yellow jar that makes you smile! SOME BY MI''s Yuja Niacin cream pairs yuja extract, a Korean citrus fruit, with 5% niacinamide. Tested non-comedogenic according to the brand, it goes on in a thin layer as part of your routine. A cheerful 60 g jar.' ELSE description_en END
WHERE slug = 'somebymi-yuja-niacin-anti-blemish-cream' OR (TRIM(brand) = 'SOME BY MI' AND TRIM(name) = 'Yuja Niacin Anti Blemish Cream');

